begin;

do $test$
declare
 actor uuid;tenant uuid;supplier uuid;material uuid;unit_id uuid;estimated_menu uuid;financial_menu uuid;
 source_type uuid;target_type uuid;alternate_type uuid;standard_type uuid;foreign_type uuid;application_type uuid;purpose uuid;method uuid;fund uuid;
 estimate jsonb;finance jsonb;payload jsonb;application jsonb;payment jsonb;rule jsonb;options jsonb;expected_date date;
 source_id uuid;copy_id uuid;index_value integer;blocked boolean;number_code text;reference_count integer;new_tenant uuid;
 ordinary_actor uuid;ordinary_tenant uuid;ordinary_role uuid;role_code text:='QA_TYPE_'||upper(left(gen_random_uuid()::text,8));
begin
 select auth_user_id into actor from public.sys_user where user_roles @>array['R_SUPER'] and auth_user_id is not null limit 1;
 select account.tenant_id,account.id into tenant,fund from public.fms_fund_account account join public.fms_currency currency on currency.id=account.currency_id where account.status='active' and account.account_type='cash' and currency.currency_code='CNY' and exists(select 1 from public.mdm_material where tenant_id=account.tenant_id and inventory_unit_id is not null) limit 1;
 select id into supplier from public.mdm_supplier where tenant_id=tenant limit 1;
 select id,inventory_unit_id into material,unit_id from public.mdm_material where tenant_id=tenant and inventory_unit_id is not null limit 1;
 select id into estimated_menu from public.sys_menu where name='FinanceEstimatedPayable';
 select id into financial_menu from public.sys_menu where name='FinancePurchasePayable';
 if actor is null or tenant is null or supplier is null then raise exception 'Missing payable type fixtures';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);perform set_config('request.headers','{}',true);
 select id into standard_type from public.mdm_document_type where tenant_id=tenant and document_type_code='AP_EST_STANDARD';
 update public.mdm_document_type set document_type_name='标准采购更名回归' where id=standard_type;
 payload:=jsonb_build_object('kind','estimated','tenant_id',tenant,'document_type_id',standard_type,'supplier_id',supplier,'business_date',current_date,'standard_purchase',false,'payable_type_rule',jsonb_build_object('standard_purchase',false),'lines',jsonb_build_array(jsonb_build_object('inventory_unit_id',unit_id,'quantity',2,'unit_price',100,'tax_rate',13)));
 blocked:=false;begin perform public.fms_save_purchase_payable_secure(payload);exception when check_violation then blocked:=true;end;
 if not blocked then raise exception 'Renaming standard type bypassed required material';end if;
 estimate:=public.fms_save_purchase_payable_secure(jsonb_set(payload,'{lines,0,material_id}',to_jsonb(material)));
 if not(estimate->>'standard_purchase')::boolean then raise exception 'Client forged standard purchase classification';end if;
 perform public.fms_act_purchase_payable_secure(array[(estimate->>'id')::uuid],'submit');perform public.fms_act_purchase_payable_secure(array[(estimate->>'id')::uuid],'approve');
 blocked:=false;begin perform public.fms_push_estimated_payable_secure((estimate->>'id')::uuid);exception when check_violation then blocked:=true;end;
 if not blocked then raise exception 'Manual standard estimate bypassed receipt-driven invoicing';end if;
 blocked:=false;begin update public.mdm_document_type set payable_standard_purchase=false where id=standard_type;exception when check_violation then blocked:=true;end;
 if not blocked then raise exception 'Builtin standard classification was disabled';end if;
 for index_value in 1..2 loop
  number_code:=upper(replace(gen_random_uuid()::text,'-',''));
  insert into public.mdm_document_type(tenant_id,menu_id,document_type_code,document_type_name,sort_order) values(tenant,financial_menu,'QA_FIN_'||number_code,'回归目标财务'||index_value,80) returning id into target_type;
  insert into public.mdm_document_type(tenant_id,menu_id,document_type_code,document_type_name,sort_order) values(tenant,financial_menu,'QA_ALT_'||number_code,'回归备用财务'||index_value,90) returning id into alternate_type;
  insert into public.mdm_document_type(tenant_id,menu_id,document_type_code,document_type_name,financial_payable_type_id) values(tenant,estimated_menu,'QA_EST_'||number_code,'回归非标暂估'||index_value,target_type) returning id into source_type;
  payload:=jsonb_build_object('kind','estimated','tenant_id',tenant,'document_type_id',source_type,'supplier_id',supplier,'business_date',current_date,'financial_payable_type_id',alternate_type,'lines',jsonb_build_array(jsonb_build_object('material_id',material,'inventory_unit_id',unit_id,'quantity',2,'unit_price',100,'tax_rate',13)));
  estimate:=public.fms_save_purchase_payable_secure(payload);source_id:=(estimate->>'id')::uuid;
  if estimate->>'financial_payable_type_id' is distinct from target_type::text then raise exception 'Client replaced authoritative type mapping';end if;
  perform public.fms_act_purchase_payable_secure(array[source_id],'submit');perform public.fms_act_purchase_payable_secure(array[source_id],'approve');
  update public.mdm_document_type set financial_payable_type_id=alternate_type,document_type_name='改名后暂估'||index_value where id=source_type;
  rule:=app_private.payable_document_type_rule(source_id);
  if rule->>'financial_payable_type_id' is distinct from target_type::text then raise exception 'Master mapping rewrote approved source rule';end if;
  if not exists(select 1 from public.get_record_delete_dependency_details('mdm_document_type',array[target_type::text],'fms_payable_financial_type_tenant_fkey') dependency where dependency.target_id=source_id::text and dependency.record_no=estimate->>'document_no') then raise exception 'Type deletion guard lost the immutable payable mapping reference';end if;
   finance:=public.fms_push_estimated_payable_secure(source_id);
   if finance->>'document_type_id' is distinct from target_type::text then raise exception 'Financial payable did not use original type mapping';end if;
   finance:=public.fms_save_purchase_payable_secure(jsonb_set(finance,'{lines,0,quantity}','1'));
   perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'submit');perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'approve');
   finance:=public.fms_push_estimated_payable_secure(source_id);
   if finance->>'document_type_id' is distinct from target_type::text then raise exception 'Partial invoicing switched to new master mapping';end if;
   perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'submit');perform public.fms_act_purchase_payable_secure(array[(finance->>'id')::uuid],'approve');
  if (app_private.purchase_payable_json(source_id)->>'unreversed_amount')::numeric<>0 then raise exception 'Type mapping change prevented original-price reversal';end if;
  estimate:=public.fms_save_purchase_payable_secure(payload);
  if estimate->>'financial_payable_type_id' is distinct from alternate_type::text then raise exception 'New document did not capture new mapping';end if;
  copy_id:=public.copy_mdm_document_type_with_menus(source_type,estimated_menu,'QA_COPY_'||number_code,'回归配置副本',false,'',100,'','primary',true,'[]'::jsonb,array[estimated_menu]);
  if(select financial_payable_type_id from public.mdm_document_type where id=copy_id) is distinct from alternate_type then raise exception 'Type copy lost payable mapping';end if;
  blocked:=false;begin update public.mdm_document_type set financial_payable_type_id=standard_type where id=source_type;exception when check_violation then blocked:=true;end;
  if not blocked then raise exception 'Estimate type accepted another estimate as its financial target';end if;
  select id into foreign_type from public.mdm_document_type where tenant_id<>tenant and financial_menu=any(menu_ids) and not payable_standard_purchase limit 1;
  blocked:=false;begin update public.mdm_document_type set financial_payable_type_id=foreign_type where id=source_type;exception when check_violation or foreign_key_violation then blocked:=true;end;
  if not blocked then raise exception 'Cross-tenant type mapping accepted';end if;
 end loop;
 expected_date:=app_private.payable_business_date();
 if app_private.payable_business_date('2026-10-31 15:59:59+00')<>date '2026-10-31' or app_private.payable_business_date('2026-10-31 16:00:00+00')<>date '2026-11-01' then raise exception 'Finance business date did not use China midnight';end if;
 perform set_config('TimeZone','UTC',true);
 if app_private.payable_business_date()<>expected_date then raise exception 'Session timezone changed finance business date';end if;
 select id into application_type from public.mdm_document_type where tenant_id=tenant and document_type_code='AP_APP_PURCHASE';
 select id into purpose from public.mdm_payment_purpose where tenant_id=tenant and code='201';
 select id into method from public.mdm_settlement_method where tenant_id=tenant and category='cash' and enabled order by code limit 1;
 application:=public.fms_save_payable_settlement_secure(jsonb_build_object('kind','application','tenant_id',tenant,'document_type_id',application_type,'lines',jsonb_build_array(jsonb_build_object('purpose_id',purpose,'supplier_id',supplier,'settlement_method_id',method,'fund_account_id',fund,'amount',10))));
 if (application->>'business_date')::date<>expected_date then raise exception 'Omitted application date used server UTC date';end if;
 perform public.fms_act_payable_settlement_secure(array[(application->>'id')::uuid],'submit');perform public.fms_act_payable_settlement_secure(array[(application->>'id')::uuid],'approve');
 payment:=public.fms_push_payable_settlement_secure((application->>'id')::uuid,'payment','application');
 if (payment->>'business_date')::date<>expected_date then raise exception 'Pushed payment date used server UTC date';end if;
 perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'submit');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'approve');perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'confirm');
 perform public.fms_act_payable_settlement_secure(array[(payment->>'id')::uuid],'cancel_payment','跨日业务日期回归');
 if exists(select 1 from public.fms_payable_payment_execution execution join public.fms_fund_ledger_entry ledger on ledger.id=execution.reversal_ledger_id where execution.document_id=(payment->>'id')::uuid and ledger.entry_date<>expected_date) then raise exception 'Cancellation reversal date used server UTC date';end if;
 select auth_user_id,tenant_id into ordinary_actor,ordinary_tenant from public.sys_user where auth_user_id is not null and status='1' and not system_protected and not user_roles @>array['R_SUPER'] and exists(select 1 from public.mdm_document_type where tenant_id=sys_user.tenant_id and financial_payable_type_id is not null) limit 1;
 if ordinary_actor is null then raise exception 'Missing ordinary type option fixture';end if;
 perform set_config('request.jwt.claim.sub','',true);
 insert into public.sys_role(tenant_id,role_code,role_name,enabled) values(ordinary_tenant,role_code,'回归单据配置',true) returning id into ordinary_role;
 insert into public.sys_role_menu(tenant_id,role_id,menu_id) select ordinary_tenant,ordinary_role,id from public.sys_menu where name='MdmDocumentType:View';
 update public.sys_user set user_roles=array[role_code] where auth_user_id=ordinary_actor;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform set_config('request.headers','{}',true);
 options:=public.mdm_financial_payable_type_options_secure(null,null);
 if jsonb_array_length(options)=0 then raise exception 'Platform-all type options empty';end if;
 select count(*) into reference_count from public.mdm_payable_financial_type((select master from public.mdm_document_type master where master.id=source_type));
 if reference_count<>1 then raise exception 'Platform-all computed type relationship missing';end if;
 perform set_config('request.headers',jsonb_build_object('x-art-tenant-scope',ordinary_tenant)::text,true);
 options:=public.mdm_financial_payable_type_options_secure(ordinary_tenant,null);
 if exists(select 1 from jsonb_array_elements(options) option join public.mdm_document_type master on master.id=(option->>'id')::uuid where master.tenant_id<>ordinary_tenant) then raise exception 'Selected tenant options leaked another tenant';end if;
 select count(*) into reference_count from public.mdm_payable_financial_type((select master from public.mdm_document_type master where master.tenant_id<>ordinary_tenant and master.financial_payable_type_id is not null limit 1));
 if reference_count<>0 then raise exception 'Selected computed relationship leaked another tenant';end if;
 blocked:=false;begin perform public.mdm_financial_payable_type_options_secure((select id from public.sys_tenant where id<>ordinary_tenant limit 1),null);exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Platform-selected read accepted explicit foreign tenant';end if;
 perform set_config('request.jwt.claim.sub',ordinary_actor::text,true);perform set_config('request.headers',jsonb_build_object('x-art-tenant-scope',(select id from public.sys_tenant where id<>ordinary_tenant limit 1))::text,true);
 options:=public.mdm_financial_payable_type_options_secure(null,null);
 if exists(select 1 from jsonb_array_elements(options) option join public.mdm_document_type master on master.id=(option->>'id')::uuid where master.tenant_id<>ordinary_tenant) then raise exception 'Forged ordinary scope leaked financial types';end if;
 select id into source_type from public.mdm_document_type where tenant_id=ordinary_tenant and financial_payable_type_id is not null limit 1;
 select count(*) into reference_count from public.mdm_payable_financial_type((select master from public.mdm_document_type master where master.id=source_type));
 if reference_count<>1 then raise exception 'Ordinary own computed type relationship unavailable';end if;
 select count(*) into reference_count from public.mdm_payable_financial_type((select master from public.mdm_document_type master where master.tenant_id<>ordinary_tenant and master.financial_payable_type_id is not null limit 1));
 if reference_count<>0 then raise exception 'Forged ordinary computed relationship leaked another tenant';end if;
 delete from public.sys_role_menu where role_id=ordinary_role;
 blocked:=false;begin perform public.mdm_financial_payable_type_options_secure(null,null);exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Missing MDM View permission accepted';end if;
 select count(*) into reference_count from public.mdm_payable_financial_type((select master from public.mdm_document_type master where master.id=source_type));
 if reference_count<>0 then raise exception 'Computed relationship bypassed MDM View permission';end if;
 if has_function_privilege('anon','public.mdm_financial_payable_type_options_secure(uuid,uuid)','execute') or has_function_privilege('anon','public.mdm_payable_financial_type(public.mdm_document_type)','execute') or has_function_privilege('authenticated','app_private.payable_business_date(timestamptz)','execute') then raise exception 'Private rule helper or financial type API leaked access';end if;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.headers','{}',true);
 for index_value in 1..2 loop
  insert into public.sys_tenant(tenant_code,tenant_name) values('qa_rule_'||replace(gen_random_uuid()::text,'-',''),'回归类型租户'||index_value) returning id into new_tenant;
  if (select count(*) from public.mdm_document_type where tenant_id=new_tenant and document_type_code in('AP_EST_STANDARD','AP_FIN_STANDARD') and payable_standard_purchase)<>2 then raise exception 'New tenant lost standard purchase rules';end if;
  if (select count(*) from public.mdm_document_type where tenant_id=new_tenant and document_type_code in('AP_EST_EXP_PUR','AP_EST_OTHER','AP_EST_EXPENSE','AP_EST_SERVICE') and financial_payable_type_id is not null)<>4 then raise exception 'New tenant lost nonstandard type mapping';end if;
  if exists(select 1 from public.mdm_document_type source join public.mdm_document_type target on target.id=source.financial_payable_type_id where source.tenant_id=new_tenant and target.tenant_id<>new_tenant) then raise exception 'New tenant retained platform target identifiers';end if;
 end loop;
end $test$;

rollback;
